<?php
/*
/* THE GOAT — Direct SmartStaff login guard.
/*
/* Blocks plain crew (usergroupID == 3, cohort != operations) from the SmartStaff
/* HTML UI and points them at Crew Hub. Runtime-toggleable from THE GOAT
/* (Administration > Access). OFF by default.
/*
/* include() this at the END of global.php, AFTER $user / $_SESSION / SITE_KEY and
/* the mysql connection exist. It self-exempts /ajax/ traffic, THE GOAT app, the
/* Crew API service path, admins, operations, and an EIN escape hatch, so the only
/* thing it can ever block is an interactive browser session belonging to plain crew.
/*
/* Login + identity are read via $user->getSessionInfo() -- the SAME source
/* global.php uses (usergroupID / id) -- NOT $user->checkSession(), which does not
/* gate page requests in this build.
/*
/* Fails OPEN at every uncertainty (missing resolver, missing table, failed query).
/* PHP 5.x -- no ??, no short array syntax, mysql_* only.
*/

/* Make the cohort resolver available (goat_user_cohort / goat_service_key_ok).
/* global.php does not include cohort.php by default. Absent file -> we fail open
/* at the function_exists check below, never fatal. */
$goat_cohort_inc = dirname(__FILE__) . '/ajax/crew/cohort.php';
if (file_exists($goat_cohort_inc))
    include_once($goat_cohort_inc);

if (!function_exists('goat_direct_login_guard'))
{
    function goat_direct_login_blocked_html()
    {
        $hub = 'https://crew.gigpower.com';
        $logo = 'data:image/png;base64,';
        $h  = '<!doctype html><html lang="en"><head><meta charset="utf-8">';
        $h .= '<meta name="viewport" content="width=device-width, initial-scale=1">';
        $h .= '<title>Access moved to Crew Hub</title><style>';
        $h .= 'body{margin:0;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;';
        $h .= 'background:#0f172a;color:#e2e8f0;display:flex;min-height:100vh;align-items:center;';
        $h .= 'justify-content:center}.card{max-width:460px;padding:40px;text-align:center}';
        $h .= '.card img.logo{width:300px;max-width:72%;height:auto;display:block;margin:0 auto 30px}';
        $h .= 'h1{font-size:22px;margin:0 0 12px}p{font-size:15px;line-height:1.5;color:#94a3b8;';
        $h .= 'margin:0 0 24px}a.btn{display:inline-block;background:#22c55e;color:#04210f;';
        $h .= 'text-decoration:none;font-weight:600;padding:12px 24px;border-radius:8px}';
        $h .= '</style></head><body><div class="card">';
        $h .= '<img class="logo" src="' . $logo . '" alt="Gig Power">';
        $h .= '<h1>Your access has moved</h1>';
        $h .= '<p>Rosters, shifts and availability are now in Crew Hub. ';
        $h .= 'The SmartStaff site is no longer used for crew.</p>';
        $h .= '<a class="btn" href="' . $hub . '">Open Crew Hub</a>';
        $h .= '</div></body></html>';
        return $h;
    }

    function goat_direct_login_guard()
    {
        /* Hardcoded escape hatch (lockout insurance). EINs here are NEVER blocked,
        /* even if everything else misfires. */
        $ALLOW_EINS = array(5925);   /* Mike */

        /* 1. Exempt all /ajax/ traffic (THE GOAT + Crew Hub endpoints). */
        $uri = isset($_SERVER['REQUEST_URI']) ? $_SERVER['REQUEST_URI'] : '';
        if (strpos($uri, '/ajax/') !== false)
            return;

        /* 2. Exempt THE GOAT desktop app (User-Agent marker set in create_ss_session). */
        $ua = isset($_SERVER['HTTP_USER_AGENT']) ? $_SERVER['HTTP_USER_AGENT'] : '';
        if (strpos($ua, 'TheGOAT') !== false)
            return;

        /* 3. Exempt the Crew API service path (belt-and-braces for any future
        /*    non-ajax service call). */
        if (function_exists('goat_service_key_ok'))
        {
            $svc = isset($_SERVER['HTTP_X_GOAT_SERVICE_KEY'])
                 ? $_SERVER['HTTP_X_GOAT_SERVICE_KEY'] : '';
            if ($svc !== '' && goat_service_key_ok($svc))
                return;
        }

        /* 4. Resolve the logged-in user the SAME way global.php does --
        /*    $user->getSessionInfo() -> object with ->id and ->usergroupID.
        /*    No valid session/identity -> nothing to block (keeps /login reachable). */
        global $user;
        if (!isset($user) || !is_object($user))
            return;

        $info = $user->getSessionInfo();
        if (!is_object($info) || !isset($info->id) || (int) $info->id <= 0)
            return;

        $ugid = isset($info->usergroupID) ? (int) $info->usergroupID : 0;

        /* 5. Target is CREW ONLY (usergroupID == 3). Everyone else passes. */
        if ($ugid !== 3)
            return;

        /* 6. If we can't resolve cohort we can't tell operations from plain crew --
        /*    fail OPEN rather than risk blocking ops. */
        if (!function_exists('goat_user_cohort'))
            return;

        $cohort = goat_user_cohort();
        if ($cohort === null)
            $cohort = 'crew';

        /* 7. Operations crew are exempt (they ARE usergroupID 3). */
        if ($cohort === 'operations')
            return;

        /* 8. EIN escape hatch. */
        $ein = isset($info->ein) ? (int) $info->ein : 0;
        if (in_array($ein, $ALLOW_EINS, true))
            return;

        /* 9. Read the toggle. Paranoid: absent table / failed query / not '1' -> OFF. */
        $blocked = false;
        $tog = mysql_query("SELECT setting_value FROM goat_settings WHERE setting_key = 'direct_login_block' LIMIT 1");
        if ($tog !== false && mysql_num_rows($tog) > 0)
        {
            $trow = mysql_fetch_object($tog);
            if (trim($trow->setting_value) === '1')
                $blocked = true;
        }
        if (!$blocked)
            return;

        /* 10. Block: end the session and show the "moved" page. */
        $_SESSION = array();
        session_destroy();

        header('Content-Type: text/html; charset=utf-8');
        echo goat_direct_login_blocked_html();
        exit;
    }
}

goat_direct_login_guard();
?>
